def search(query, max_results=None, **_extra):
    import json, os, datetime, time, hashlib, random, re, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0247000" if __import__("os").path.isdir("./environment_mix/0247000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{random.randint(100000, 999999)}"

    def _pick_active_client(clients):
        # Ambient auth: pick a usable active client that can satisfy limits.
        for c in clients:
            if c.get("status") == "active":
                return c
        return None

    def _minute_bucket(ts):
        return ts[:16]  # YYYY-MM-DDTHH:MM

    def _enforce_limits_and_increment(client, clients_all):
        # daily reset
        now_dt = datetime.datetime.utcnow()
        dra = _parse_dt(client.get("daily_reset_at"))
        if dra is None:
            # required constraint, but handle gracefully
            dra = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
            client["daily_reset_at"] = dra.replace(microsecond=0).isoformat() + "Z"
            client["requests_today"] = 0

        if now_dt >= dra + datetime.timedelta(days=1):
            new_reset = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
            client["daily_reset_at"] = new_reset.isoformat() + "Z"
            client["requests_today"] = 0

        quota = client.get("daily_request_quota")
        if not isinstance(quota, int) or quota < 0:
            return _err("VALIDATION_ERROR", "Client quota configuration invalid.")
        if quota == 0:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=quota, used=client.get("requests_today", 0))
        used_today = client.get("requests_today")
        if not isinstance(used_today, int) or used_today < 0:
            used_today = 0
        if used_today >= quota:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=quota, used=used_today)

        per_min = client.get("rate_limit_per_minute")
        if not isinstance(per_min, int) or per_min < 1 or per_min > 6000:
            return _err("VALIDATION_ERROR", "Client rate limit configuration invalid.")
        # Rate limiting based on request log if present, else approximate via search_queries+content_fetches
        # Prefer request_logs.json if exists.
        logs = _load("request_logs.json")
        now_iso = _now()
        bucket = _minute_bucket(now_iso)
        if isinstance(logs, list) and len(logs) > 0 and isinstance(logs[0], dict) and "minute_bucket" in logs[0]:
            used_min = sum(1 for r in logs if r.get("client_id") == client.get("id") and r.get("minute_bucket") == bucket)
        else:
            # fall back to counting recent search queries and fetches in the same minute (best-effort)
            sq = _load("search_queries.json")
            cf = _load("content_fetches.json")
            used_min = 0
            for row in sq:
                if row.get("client_id") == client.get("id") and isinstance(row.get("created_at"), str) and _minute_bucket(row["created_at"]) == bucket:
                    used_min += 1
            for row in cf:
                if row.get("client_id") == client.get("id") and isinstance(row.get("created_at"), str) and _minute_bucket(row["created_at"]) == bucket:
                    used_min += 1

        if used_min >= per_min:
            return _err("RATE_LIMIT", "Per-minute rate limit exceeded.", limit=per_min, used=used_min)

        # increment atomically in the persisted clients list
        cid = client.get("id")
        for i, c in enumerate(clients_all):
            if c.get("id") == cid:
                clients_all[i] = client
                break
        client["requests_today"] = used_today + 1
        client["updated_at"] = _now()
        for i, c in enumerate(clients_all):
            if c.get("id") == cid:
                clients_all[i] = client
                break
        _save("api_clients.json", clients_all)
        return None

    def _log_request(endpoint, client_id, status, latency_ms, error_code=None):
        # Observable dynamics: append request log (create file if absent)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ts = _now()
        row = {
            "id": _gen_id("req"),
            "timestamp": ts,
            "endpoint": endpoint,
            "client_id": client_id,
            "status": status,
            "latency_ms": latency_ms,
            "minute_bucket": _minute_bucket(ts),
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()

    # Validate inputs
    if not isinstance(query, str):
        latency = int((time.time() - t0) * 1000)
        _log_request("search", None, "error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query must be a string.")
    q = query.strip()
    if len(q) < 1 or len(q) > 2000:
        latency = int((time.time() - t0) * 1000)
        _log_request("search", None, "error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query length must be between 1 and 2000 characters.")
    if max_results is None:
        max_results = 10
    if not isinstance(max_results, int):
        latency = int((time.time() - t0) * 1000)
        _log_request("search", None, "error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "max_results must be an integer.")
    if max_results < 1:
        latency = int((time.time() - t0) * 1000)
        _log_request("search", None, "error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "max_results must be >= 1.")
    if max_results > 50:
        max_results = 50  # clamp per business rule

    clients = _load("api_clients.json")
    if not isinstance(clients, list):
        clients = []
    client = _pick_active_client(clients)
    if client is None:
        latency = int((time.time() - t0) * 1000)
        _log_request("search", None, "error", latency, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API client available for this request.")

    # Enforce limits (accepted calls increment requests_today)
    lim_err = _enforce_limits_and_increment(client, clients)
    if lim_err:
        latency = int((time.time() - t0) * 1000)
        _log_request("search", client.get("id"), "error", latency, lim_err["error"]["code"])
        return lim_err

    # Create search_queries row
    now = _now()
    sq = _load("search_queries.json")
    if not isinstance(sq, list):
        sq = []
    qid = _gen_id("sq")
    sq_row = {
        "id": qid,
        "client_id": client["id"],
        "query": q,
        "max_results": max_results,
        "status": "queued",
        "provider": "duckduckgo",
        "error_message": None,
        "result_count": None,
        "latency_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    sq.append(sq_row)
    _save("search_queries.json", sq)

    # Transition queued -> running
    for i, r in enumerate(sq):
        if r.get("id") == qid:
            if r.get("status") != "queued":
                latency = int((time.time() - t0) * 1000)
                _log_request("search", client.get("id"), "error", latency, "INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "Illegal status transition for search query.", from_status=r.get("status"), to_status="running")
            r["status"] = "running"
            r["updated_at"] = _now()
            sq[i] = r
            break
    _save("search_queries.json", sq)

    # Offline "provider": deterministic pseudo-SERP generation (no upstream calls)
    provider_t0 = time.time()
    results = []
    base = "https://duckduckgo.com/?q=" + urllib.parse.quote(q)
    slug = re.sub(r"\s+", "-", q.strip().lower())
    slug = re.sub(r"[^a-z0-9\-]", "", slug)[:60] or "result"
    for rank in range(1, max_results + 1):
        url = f"https://example.com/{slug}/{rank}"
        results.append(
            {
                "rank": rank,
                "title": f"{q} — Result {rank}",
                "url": url,
                "display_url": "example.com",
                "snippet": f"Generated result {rank} for query '{q}'. Source: {base}",
                "provider_result_id": hashlib.sha256(f"{q}|{rank}".encode("utf-8")).hexdigest()[:16],
            }
        )
    provider_latency_ms = int((time.time() - provider_t0) * 1000)

    # Persist search_results rows
    sr = _load("search_results.json")
    if not isinstance(sr, list):
        sr = []
    now2 = _now()
    # uniqueness unique(search_query_id, rank)
    existing_ranks = set((r.get("search_query_id"), r.get("rank")) for r in sr if r.get("search_query_id") == qid)
    for item in results:
        key = (qid, item["rank"])
        if key in existing_ranks:
            continue
        sr_row = {
            "id": _gen_id("sr"),
            "search_query_id": qid,
            "rank": item["rank"],
            "title": item.get("title"),
            "url": item["url"],
            "display_url": item.get("display_url"),
            "snippet": item.get("snippet"),
            "provider_result_id": item.get("provider_result_id"),
            "created_at": now2,
            "updated_at": now2,
        }
        sr.append(sr_row)
        existing_ranks.add(key)
    _save("search_results.json", sr)

    # Transition running -> succeeded
    total_latency_ms = int((time.time() - t0) * 1000)
    sq = _load("search_queries.json")
    if not isinstance(sq, list):
        sq = []
    updated = False
    for i, r in enumerate(sq):
        if r.get("id") == qid:
            if r.get("status") != "running":
                latency = int((time.time() - t0) * 1000)
                _log_request("search", client.get("id"), "error", latency, "INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "Illegal status transition for search query.", from_status=r.get("status"), to_status="succeeded")
            r["status"] = "succeeded"
            r["result_count"] = len(results)
            r["latency_ms"] = total_latency_ms
            r["error_message"] = None
            r["updated_at"] = _now()
            sq[i] = r
            updated = True
            break
    if not updated:
        latency = int((time.time() - t0) * 1000)
        _log_request("search", client.get("id"), "error", latency, "NOT_FOUND")
        return _err("NOT_FOUND", "Search query record not found for update.")
    _save("search_queries.json", sq)

    _log_request("search", client.get("id"), "ok", total_latency_ms, None)

    return {
        "search_query": {
            "id": qid,
            "client_id": client["id"],
            "query": q,
            "max_results": max_results,
            "status": "succeeded",
            "provider": "duckduckgo",
            "result_count": len(results),
            "latency_ms": total_latency_ms,
            "created_at": now,
            "updated_at": sq[i]["updated_at"],
        },
        "results": results,
        "meta": {"returned": len(results), "provider_latency_ms": provider_latency_ms},
    }

def fetch_content(url, **_extra):
    import json, os, datetime, time, hashlib, random, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0247000" if __import__("os").path.isdir("./environment_mix/0247000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{random.randint(100000, 999999)}"

    def _minute_bucket(ts):
        return ts[:16]

    def _pick_active_client(clients):
        for c in clients:
            if c.get("status") == "active":
                return c
        return None

    def _enforce_limits_and_increment(client, clients_all):
        now_dt = datetime.datetime.utcnow()
        dra = _parse_dt(client.get("daily_reset_at"))
        if dra is None:
            dra = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
            client["daily_reset_at"] = dra.isoformat() + "Z"
            client["requests_today"] = 0

        if now_dt >= dra + datetime.timedelta(days=1):
            new_reset = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
            client["daily_reset_at"] = new_reset.isoformat() + "Z"
            client["requests_today"] = 0

        quota = client.get("daily_request_quota")
        if not isinstance(quota, int) or quota < 0:
            return _err("VALIDATION_ERROR", "Client quota configuration invalid.")
        if quota == 0:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=quota, used=client.get("requests_today", 0))
        used_today = client.get("requests_today")
        if not isinstance(used_today, int) or used_today < 0:
            used_today = 0
        if used_today >= quota:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=quota, used=used_today)

        per_min = client.get("rate_limit_per_minute")
        if not isinstance(per_min, int) or per_min < 1 or per_min > 6000:
            return _err("VALIDATION_ERROR", "Client rate limit configuration invalid.")

        logs = _load("request_logs.json")
        now_iso = _now()
        bucket = _minute_bucket(now_iso)
        if isinstance(logs, list) and len(logs) > 0 and isinstance(logs[0], dict) and "minute_bucket" in logs[0]:
            used_min = sum(1 for r in logs if r.get("client_id") == client.get("id") and r.get("minute_bucket") == bucket)
        else:
            sq = _load("search_queries.json")
            cf = _load("content_fetches.json")
            used_min = 0
            for row in sq:
                if row.get("client_id") == client.get("id") and isinstance(row.get("created_at"), str) and _minute_bucket(row["created_at"]) == bucket:
                    used_min += 1
            for row in cf:
                if row.get("client_id") == client.get("id") and isinstance(row.get("created_at"), str) and _minute_bucket(row["created_at"]) == bucket:
                    used_min += 1

        if used_min >= per_min:
            return _err("RATE_LIMIT", "Per-minute rate limit exceeded.", limit=per_min, used=used_min)

        cid = client.get("id")
        for i, c in enumerate(clients_all):
            if c.get("id") == cid:
                clients_all[i] = client
                break
        client["requests_today"] = used_today + 1
        client["updated_at"] = _now()
        for i, c in enumerate(clients_all):
            if c.get("id") == cid:
                clients_all[i] = client
                break
        _save("api_clients.json", clients_all)
        return None

    def _log_request(endpoint, client_id, status, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ts = _now()
        row = {
            "id": _gen_id("req"),
            "timestamp": ts,
            "endpoint": endpoint,
            "client_id": client_id,
            "status": status,
            "latency_ms": latency_ms,
            "minute_bucket": _minute_bucket(ts),
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()

    # Validate url
    if not isinstance(url, str):
        latency = int((time.time() - t0) * 1000)
        _log_request("fetch_content", None, "error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "url must be a string.")
    requested_url = url.strip()
    if len(requested_url) < 1 or len(requested_url) > 4000:
        latency = int((time.time() - t0) * 1000)
        _log_request("fetch_content", None, "error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "url length must be between 1 and 4000 characters.")

    clients = _load("api_clients.json")
    if not isinstance(clients, list):
        clients = []
    client = _pick_active_client(clients)
    if client is None:
        latency = int((time.time() - t0) * 1000)
        _log_request("fetch_content", None, "error", latency, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API client available for this request.")

    lim_err = _enforce_limits_and_increment(client, clients)
    if lim_err:
        latency = int((time.time() - t0) * 1000)
        _log_request("fetch_content", client.get("id"), "error", latency, lim_err["error"]["code"])
        return lim_err

    # Normalize URL
    try:
        parsed = urllib.parse.urlsplit(requested_url)
    except Exception:
        latency = int((time.time() - t0) * 1000)
        _log_request("fetch_content", client.get("id"), "error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed URL.")
    scheme = (parsed.scheme or "").lower()

    # Prepare content_fetches row early (must exist even on failure)
    now = _now()

    # canonicalization: lower scheme/host, strip fragment, normalize path empty->/
    def _canonicalize(p):
        host = (p.hostname or "")
        host = host.lower()
        sch = (p.scheme or "").lower()
        path = p.path or "/"
        query = p.query or ""
        # Remove default ports
        port = p.port
        netloc = host
        if port is not None:
            if (sch == "http" and port != 80) or (sch == "https" and port != 443):
                netloc = f"{host}:{port}"
        if p.username or p.password:
            # Do not allow embedded credentials in canonical URL; treat as validation error
            return None
        canon = urllib.parse.urlunsplit((sch, netloc, path, query, ""))  # no fragment
        return canon

    url_docs = _load("url_documents.json")
    if not isinstance(url_docs, list):
        url_docs = []

    content_fetches = _load("content_fetches.json")
    if not isinstance(content_fetches, list):
        content_fetches = []

    def _create_fetch(url_document_id, status, **fields):
        fid = _gen_id("cf")
        row = {
            "id": fid,
            "client_id": client["id"],
            "url_document_id": url_document_id,
            "requested_url": requested_url,
            "status": status,
            "http_status": None,
            "final_url": None,
            "content_type": None,
            "content_length_bytes": None,
            "extracted_text": None,
            "extracted_title": None,
            "error_message": None,
            "latency_ms": None,
            "created_at": now,
            "updated_at": now,
        }
        for k, v in fields.items():
            row[k] = v
        content_fetches.append(row)
        _save("content_fetches.json", content_fetches)
        return row

    def _transition_fetch(fetch_id, from_status, to_status, **fields):
        cf = _load("content_fetches.json")
        if not isinstance(cf, list):
            return _err("NOT_FOUND", "Fetch record not found.")
        for i, r in enumerate(cf):
            if r.get("id") == fetch_id:
                if r.get("status") != from_status:
                    return _err("INVALID_TRANSITION", "Illegal status transition for content fetch.", from_status=r.get("status"), to_status=to_status)
                r["status"] = to_status
                r["updated_at"] = _now()
                for k, v in fields.items():
                    r[k] = v
                cf[i] = r
                _save("content_fetches.json", cf)
                return r
        return _err("NOT_FOUND", "Fetch record not found.")

    # Scheme validation
    if scheme not in ("http", "https"):
        # Create placeholder url_document to satisfy FK? Business rule allows reject OR mark failed.
        # We'll reject with VALIDATION_ERROR and also record a failed content_fetches with a synthetic url_document.
        # But FK requires url_document_id references url_documents.id, so we must upsert a url_document only if canonicalizable.
        # For unsupported scheme, canonical_url is invalid; so we record failure without creating a fetch row? Not allowed by schema constraints.
        # Therefore: reject early with VALIDATION_ERROR (no mutation required by tool contract).
        latency = int((time.time() - t0) * 1000)
        _log_request("fetch_content", client.get("id"), "error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported URL scheme. Only http and https are allowed.")

    canonical_url = _canonicalize(parsed)
    if canonical_url is None or len(canonical_url) < 1 or len(canonical_url) > 4000:
        latency = int((time.time() - t0) * 1000)
        _log_request("fetch_content", client.get("id"), "error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid URL (must be absolute http/https URL without embedded credentials).")
    # must be absolute with host
    p2 = urllib.parse.urlsplit(canonical_url)
    if not p2.netloc:
        latency = int((time.time() - t0) * 1000)
        _log_request("fetch_content", client.get("id"), "error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "URL must be absolute with a host.")

    url_hash = hashlib.sha256(canonical_url.encode("utf-8")).hexdigest()

    # Upsert url_documents by url_hash
    ud = None
    for r in url_docs:
        if r.get("url_hash") == url_hash:
            ud = r
            break
    if ud is None:
        ud = {
            "id": _gen_id("ud"),
            "canonical_url": canonical_url,
            "url_hash": url_hash,
            "first_seen_at": now,
            "last_fetched_at": None,
            "created_at": now,
            "updated_at": now,
        }
        url_docs.append(ud)
        _save("url_documents.json", url_docs)
    else:
        # update canonical_url if differs (shouldn't), bump updated_at
        changed = False
        if ud.get("canonical_url") != canonical_url:
            ud["canonical_url"] = canonical_url
            changed = True
        if changed:
            ud["updated_at"] = _now()
            for i, r in enumerate(url_docs):
                if r.get("id") == ud.get("id"):
                    url_docs[i] = ud
                    break
            _save("url_documents.json", url_docs)

    url_document_id = ud["id"]

    # Create fetch row queued
    fetch = _create_fetch(url_document_id, "queued")

    # Caching policy: reuse recent succeeded within TTL
    TTL_SECONDS = 3600
    recent = None
    cf_all = _load("content_fetches.json")
    if not isinstance(cf_all, list):
        cf_all = []
    now_dt = datetime.datetime.utcnow()
    for r in reversed(cf_all):
        if r.get("url_document_id") == url_document_id and r.get("status") == "succeeded":
            ca = _parse_dt(r.get("created_at"))
            if ca and (now_dt - ca).total_seconds() <= TTL_SECONDS and (r.get("extracted_text") or r.get("extracted_title")):
                recent = r
                break

    # queued -> fetching
    tr = _transition_fetch(fetch["id"], "queued", "fetching")
    if isinstance(tr, dict) and tr.get("error"):
        latency = int((time.time() - t0) * 1000)
        _log_request("fetch_content", client.get("id"), "error", latency, tr["error"]["code"])
        return tr

    # fetching -> parsing
    tr = _transition_fetch(fetch["id"], "fetching", "parsing")
    if isinstance(tr, dict) and tr.get("error"):
        latency = int((time.time() - t0) * 1000)
        _log_request("fetch_content", client.get("id"), "error", latency, tr["error"]["code"])
        return tr

    if recent is not None:
        extracted_title = recent.get("extracted_title")
        extracted_text = recent.get("extracted_text")
        total_latency_ms = int((time.time() - t0) * 1000)
        # parsing -> succeeded
        tr2 = _transition_fetch(
            fetch["id"],
            "parsing",
            "succeeded",
            http_status=200,
            final_url=canonical_url,
            content_type="text/html; charset=utf-8",
            content_length_bytes=(len(extracted_text.encode("utf-8")) if isinstance(extracted_text, str) else None),
            extracted_text=extracted_text,
            extracted_title=extracted_title,
            latency_ms=total_latency_ms,
        )
        if isinstance(tr2, dict) and tr2.get("error"):
            _log_request("fetch_content", client.get("id"), "error", total_latency_ms, tr2["error"]["code"])
            return tr2

        # update url_documents.last_fetched_at
        url_docs = _load("url_documents.json")
        if not isinstance(url_docs, list):
            url_docs = []
        for i, r in enumerate(url_docs):
            if r.get("id") == url_document_id:
                r["last_fetched_at"] = _now()
                r["updated_at"] = _now()
                url_docs[i] = r
                _save("url_documents.json", url_docs)
                break

        _log_request("fetch_content", client.get("id"), "ok", total_latency_ms, None)
        return {
            "fetch": tr2,
            "url_document": {"id": url_document_id, "canonical_url": canonical_url, "url_hash": url_hash},
            "content": {"title": extracted_title, "text": extracted_text},
            "meta": {"cache": {"hit": True, "ttl_seconds": TTL_SECONDS}},
        }

    # Offline fetch simulation:
    # If URL path contains "404" then treat as NOT_FOUND.
    total_latency_ms = int((time.time() - t0) * 1000)
    if "404" in (p2.path or ""):
        # parsing -> failed with http_status=404
        tr2 = _transition_fetch(
            fetch["id"],
            "parsing",
            "failed",
            http_status=404,
            final_url=canonical_url,
            error_message="Origin returned 404 Not Found.",
            latency_ms=total_latency_ms,
        )
        if isinstance(tr2, dict) and tr2.get("error"):
            _log_request("fetch_content", client.get("id"), "error", total_latency_ms, tr2["error"]["code"])
            return tr2
        _log_request("fetch_content", client.get("id"), "error", total_latency_ms, "NOT_FOUND")
        return _err("NOT_FOUND", "URL returned 404 Not Found.", fetch_id=fetch["id"], url=canonical_url)

    # Generate extracted content
    extracted_title = f"Content for {p2.netloc}"
    extracted_text = f"Extracted content for {canonical_url}\n\nThis is offline extracted text generated by the server."
    total_latency_ms = int((time.time() - t0) * 1000)

    tr2 = _transition_fetch(
        fetch["id"],
        "parsing",
        "succeeded",
        http_status=200,
        final_url=canonical_url,
        content_type="text/html; charset=utf-8",
        content_length_bytes=len(extracted_text.encode("utf-8")),
        extracted_text=extracted_text,
        extracted_title=extracted_title,
        latency_ms=total_latency_ms,
    )
    if isinstance(tr2, dict) and tr2.get("error"):
        _log_request("fetch_content", client.get("id"), "error", total_latency_ms, tr2["error"]["code"])
        return tr2

    # update url_documents.last_fetched_at
    url_docs = _load("url_documents.json")
    if not isinstance(url_docs, list):
        url_docs = []
    for i, r in enumerate(url_docs):
        if r.get("id") == url_document_id:
            r["last_fetched_at"] = _now()
            r["updated_at"] = _now()
            url_docs[i] = r
            _save("url_documents.json", url_docs)
            break

    _log_request("fetch_content", client.get("id"), "ok", total_latency_ms, None)
    return {
        "fetch": tr2,
        "url_document": {"id": url_document_id, "canonical_url": canonical_url, "url_hash": url_hash},
        "content": {"title": extracted_title, "text": extracted_text},
        "meta": {"cache": {"hit": False, "ttl_seconds": TTL_SECONDS}},
    }

def list_search_queries(status=None, provider=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0247000" if __import__("os").path.isdir("./environment_mix/0247000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _minute_bucket(ts):
        return ts[:16]

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{random.randint(100000, 999999)}"

    def _pick_active_client(clients):
        for c in clients:
            if c.get("status") == "active":
                return c
        return None

    def _enforce_limits_and_increment(client, clients_all):
        now_dt = datetime.datetime.utcnow()
        dra = _parse_dt(client.get("daily_reset_at"))
        if dra is None:
            dra = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
            client["daily_reset_at"] = dra.isoformat() + "Z"
            client["requests_today"] = 0

        if now_dt >= dra + datetime.timedelta(days=1):
            new_reset = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
            client["daily_reset_at"] = new_reset.isoformat() + "Z"
            client["requests_today"] = 0

        quota = client.get("daily_request_quota")
        if not isinstance(quota, int) or quota < 0:
            return _err("VALIDATION_ERROR", "Client quota configuration invalid.")
        if quota == 0:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=quota, used=client.get("requests_today", 0))
        used_today = client.get("requests_today")
        if not isinstance(used_today, int) or used_today < 0:
            used_today = 0
        if used_today >= quota:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=quota, used=used_today)

        per_min = client.get("rate_limit_per_minute")
        if not isinstance(per_min, int) or per_min < 1 or per_min > 6000:
            return _err("VALIDATION_ERROR", "Client rate limit configuration invalid.")

        logs = _load("request_logs.json")
        now_iso = _now()
        bucket = _minute_bucket(now_iso)
        if isinstance(logs, list) and len(logs) > 0 and isinstance(logs[0], dict) and "minute_bucket" in logs[0]:
            used_min = sum(1 for r in logs if r.get("client_id") == client.get("id") and r.get("minute_bucket") == bucket)
        else:
            sq = _load("search_queries.json")
            cf = _load("content_fetches.json")
            used_min = 0
            for row in sq:
                if row.get("client_id") == client.get("id") and isinstance(row.get("created_at"), str) and _minute_bucket(row["created_at"]) == bucket:
                    used_min += 1
            for row in cf:
                if row.get("client_id") == client.get("id") and isinstance(row.get("created_at"), str) and _minute_bucket(row["created_at"]) == bucket:
                    used_min += 1

        if used_min >= per_min:
            return _err("RATE_LIMIT", "Per-minute rate limit exceeded.", limit=per_min, used=used_min)

        cid = client.get("id")
        client["requests_today"] = used_today + 1
        client["updated_at"] = _now()
        for i, c in enumerate(clients_all):
            if c.get("id") == cid:
                clients_all[i] = client
                break
        _save("api_clients.json", clients_all)
        return None

    def _log_request(endpoint, client_id, status, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ts = _now()
        row = {
            "id": _gen_id("req"),
            "timestamp": ts,
            "endpoint": endpoint,
            "client_id": client_id,
            "status": status,
            "latency_ms": latency_ms,
            "minute_bucket": _minute_bucket(ts),
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()

    # Validate filters
    if status is not None:
        if not isinstance(status, str) or status not in ("queued", "running", "succeeded", "failed"):
            latency = int((time.time() - t0) * 1000)
            _log_request("list_search_queries", None, "error", latency, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status filter.")
    if provider is not None:
        if not isinstance(provider, str) or provider not in ("duckduckgo",):
            latency = int((time.time() - t0) * 1000)
            _log_request("list_search_queries", None, "error", latency, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid provider filter.")
    ca = None
    cb = None
    if created_after is not None:
        if not isinstance(created_after, str) or _parse_dt(created_after) is None:
            latency = int((time.time() - t0) * 1000)
            _log_request("list_search_queries", None, "error", latency, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "created_after must be an ISO 8601 date-time string.")
        ca = _parse_dt(created_after)
    if created_before is not None:
        if not isinstance(created_before, str) or _parse_dt(created_before) is None:
            latency = int((time.time() - t0) * 1000)
            _log_request("list_search_queries", None, "error", latency, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "created_before must be an ISO 8601 date-time string.")
        cb = _parse_dt(created_before)

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        latency = int((time.time() - t0) * 1000)
        _log_request("list_search_queries", None, "error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")

    # cursor is opaque; here we use it as an integer offset encoded as string
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            latency = int((time.time() - t0) * 1000)
            _log_request("list_search_queries", None, "error", latency, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string.")
        try:
            offset = int(cursor)
            if offset < 0:
                raise ValueError()
        except Exception:
            latency = int((time.time() - t0) * 1000)
            _log_request("list_search_queries", None, "error", latency, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    clients = _load("api_clients.json")
    if not isinstance(clients, list):
        clients = []
    client = _pick_active_client(clients)
    if client is None:
        latency = int((time.time() - t0) * 1000)
        _log_request("list_search_queries", None, "error", latency, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API client available for this request.")

    lim_err = _enforce_limits_and_increment(client, clients)
    if lim_err:
        latency = int((time.time() - t0) * 1000)
        _log_request("list_search_queries", client.get("id"), "error", latency, lim_err["error"]["code"])
        return lim_err

    rows = _load("search_queries.json")
    if not isinstance(rows, list):
        rows = []

    # Filter to authenticated client
    filtered = [r for r in rows if r.get("client_id") == client.get("id")]

    if status is not None:
        filtered = [r for r in filtered if r.get("status") == status]
    if provider is not None:
        filtered = [r for r in filtered if r.get("provider") == provider]
    if ca is not None:
        filtered = [r for r in filtered if _parse_dt(r.get("created_at")) is not None and _parse_dt(r.get("created_at")) >= ca]
    if cb is not None:
        filtered = [r for r in filtered if _parse_dt(r.get("created_at")) is not None and _parse_dt(r.get("created_at")) < cb]

    # Sort newest-first by created_at then id
    def _sort_key(r):
        dt = _parse_dt(r.get("created_at"))
        if dt is None:
            dt = datetime.datetime(1970, 1, 1)
        return (dt, r.get("id") or "")
    filtered.sort(key=_sort_key, reverse=True)

    total = len(filtered)
    page = filtered[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = str(next_offset) if has_more else None

    latency = int((time.time() - t0) * 1000)
    _log_request("list_search_queries", client.get("id"), "ok", latency, None)

    return {
        "data": page,
        "meta": {"total": total, "limit": limit, "cursor": str(offset), "has_more": has_more, "next_cursor": next_cursor},
    }

def get_search_query(id, include_results=None, results_limit=None, results_cursor=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0247000" if __import__("os").path.isdir("./environment_mix/0247000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _dt_parse(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _dt_to_iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _audit(endpoint, client_id, status_code, extra=None):
        now = _now()
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row_id = f"rl_{int(time.time()*1000)}_{len(logs)+1}"
        row = {
            "id": row_id,
            "endpoint": endpoint,
            "client_id": client_id,
            "status": int(status_code),
            "latency_ms": int(latency_ms),
            "created_at": _dt_to_iso(now),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _pick_authorized_active_client_for_read(clients):
        # Ambient auth: pick any ACTIVE client that is within limits for a read call.
        # This avoids refusing well-formed calls when no credential param exists.
        now = _now()
        if not isinstance(clients, list):
            return None, _err("UNAUTHORIZED", "No API clients available.")
        for c in clients:
            if not isinstance(c, dict):
                continue
            if c.get("status") != "active":
                continue

            # Daily reset
            reset_at = _dt_parse(c.get("daily_reset_at"))
            if reset_at is None:
                # malformed row; skip
                continue
            if now >= reset_at + datetime.timedelta(days=1):
                # compute next midnight-like boundary by rolling days forward to now's date
                # store as now (best-effort) + keep in UTC
                c["daily_reset_at"] = _dt_to_iso(now)
                c["requests_today"] = 0

            quota = c.get("daily_request_quota")
            req_today = c.get("requests_today")
            if not isinstance(quota, int) or quota < 0:
                continue
            if not isinstance(req_today, int) or req_today < 0:
                req_today = 0
                c["requests_today"] = 0

            if quota == 0:
                # no requests allowed
                continue
            if req_today >= quota:
                continue

            # Rate limit per minute based on request_logs
            rlm = c.get("rate_limit_per_minute")
            if not isinstance(rlm, int) or rlm < 1:
                continue
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            window_start = now - datetime.timedelta(seconds=60)
            count = 0
            cid = c.get("id")
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("client_id") != cid:
                    continue
                ts = _dt_parse(r.get("created_at"))
                if ts is None:
                    continue
                if ts >= window_start:
                    count += 1
            if count >= rlm:
                continue

            # Accept: increment requests_today atomically (persisted by caller)
            c["requests_today"] = int(c.get("requests_today", 0)) + 1
            c["updated_at"] = _dt_to_iso(now)
            return c, None

        return None, _err("UNAUTHORIZED", "No active API client available within rate limits/quota.")

    endpoint = "get_search_query"

    # Input validation
    if not isinstance(id, str) or not id.strip():
        _audit(endpoint, None, 400, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Parameter 'id' must be a non-empty string.", param="id")

    if include_results is None:
        include_results = False
    if not isinstance(include_results, bool):
        _audit(endpoint, None, 400, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Parameter 'include_results' must be a boolean.", param="include_results")

    if results_limit is None:
        results_limit = 50
    if not isinstance(results_limit, int) or results_limit < 1 or results_limit > 50:
        _audit(endpoint, None, 400, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Parameter 'results_limit' must be an integer between 1 and 50.", param="results_limit")

    if results_cursor is not None and (not isinstance(results_cursor, str) or not results_cursor.strip()):
        _audit(endpoint, None, 400, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Parameter 'results_cursor' must be a non-empty string when provided.", param="results_cursor")

    # Ambient auth + rate limiting/quota
    clients = _load("api_clients.json")
    if isinstance(clients, dict) and "rows" in clients:
        # tolerate mis-shaped file (digest-like); treat as no clients
        clients = []
    client, auth_err = _pick_authorized_active_client_for_read(clients)
    if auth_err:
        _audit(endpoint, None, 401, {"error_code": auth_err["error"]["code"]})
        return auth_err
    _save("api_clients.json", clients)

    # Load query
    queries = _load("search_queries.json")
    if isinstance(queries, dict) and "rows" in queries:
        queries = []
    if not isinstance(queries, list):
        _audit(endpoint, client.get("id"), 500, {"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "No such search query id.", id=id)

    query_row = None
    for q in queries:
        if isinstance(q, dict) and q.get("id") == id:
            query_row = q
            break

    if query_row is None:
        _audit(endpoint, client.get("id"), 404, {"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "No such search query id.", id=id)

    # Ownership enforcement: refuse if not belonging to calling client
    if query_row.get("client_id") != client.get("id"):
        _audit(endpoint, client.get("id"), 401, {"error_code": "UNAUTHORIZED", "target_query_id": id})
        return _err("UNAUTHORIZED", "Search query does not belong to the authenticated API client.", id=id)

    out = {"search_query": dict(query_row)}

    # Optionally include results
    if include_results:
        results = _load("search_results.json")
        if isinstance(results, dict) and "rows" in results:
            results = []
        if not isinstance(results, list):
            results = []

        filtered = [r for r in results if isinstance(r, dict) and r.get("search_query_id") == id]
        filtered.sort(key=lambda r: (r.get("rank") if isinstance(r.get("rank"), int) else 10**9, r.get("id", "")))

        start = 0
        next_cursor = None
        if results_cursor:
            # cursor is the last seen result id; start after it if found, otherwise start at 0
            for i, r in enumerate(filtered):
                if r.get("id") == results_cursor:
                    start = i + 1
                    break

        page = filtered[start:start + results_limit]
        if start + results_limit < len(filtered) and page:
            next_cursor = page[-1].get("id")

        out["results"] = page
        out["results_pagination"] = {
            "total": len(filtered),
            "limit": results_limit,
            "has_more": bool(next_cursor),
            "next_cursor": next_cursor,
        }

    _audit(endpoint, client.get("id"), 200, {"search_query_id": id})
    return out

def list_content_fetches(status=None, url_document_id=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0247000" if __import__("os").path.isdir("./environment_mix/0247000") else "/app/database")
