            logs = []
        row = {
            "id": "rl_" + hashlib.sha256((endpoint + "|" + str(client_id) + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "client_id": client_id,
            "status": status_code,
            "latency_ms": int(latency_ms),
            "created_at": _dt_to_iso(now),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _resolve_active_client_and_enforce_limits(endpoint_name):
        clients = _load("api_clients.json")
        if not isinstance(clients, list):
            clients = []
        content_fetches = _load("content_fetches.json")
        if not isinstance(content_fetches, list):
            content_fetches = []
        # Ambient auth: pick an active client that can serve this call under limits.
        # To avoid denying service when multiple clients exist, choose any eligible client.
        eligible = []
        for c in clients:
            if not isinstance(c, dict):
                continue
            if c.get("status") != "active":
                continue
            client_id = c.get("id")
            if not isinstance(client_id, str) or not client_id:
                continue

            # daily reset
            reset_at = _dt_parse(c.get("daily_reset_at")) if isinstance(c.get("daily_reset_at"), str) else None
            if reset_at is None:
                # schema says not null; treat unusable
                continue
            if reset_at.tzinfo is None:
                reset_at = reset_at.replace(tzinfo=datetime.timezone.utc)

            requests_today = c.get("requests_today")
            if not isinstance(requests_today, int) or requests_today < 0:
                continue

            quota = c.get("daily_request_quota")
            if not isinstance(quota, int) or quota < 0 or quota > 1000000:
                continue

            # reset daily counter if needed (best-effort)
            if now >= reset_at + datetime.timedelta(days=1):
                # advance reset_at to last midnight-ish step in whole-day increments
                days = (now - reset_at).days
                if days < 1:
                    days = 1
                reset_at2 = reset_at + datetime.timedelta(days=days)
                c["daily_reset_at"] = _dt_to_iso(reset_at2)
                c["requests_today"] = 0
                requests_today = 0

            # quota enforcement (quota=0 means none allowed)
            if quota == 0:
                continue
            if requests_today >= quota:
                continue

            rpm = c.get("rate_limit_per_minute")
            if not isinstance(rpm, int) or rpm < 1 or rpm > 6000:
                continue

            # rate limit: count this client's requests within last 60s using request_logs if present,
            # else approximate using content_fetches created_at.
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            cutoff = now - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("client_id") != client_id:
                    continue
                ts = _dt_parse(r.get("created_at")) if isinstance(r.get("created_at"), str) else None
                if ts is None:
                    continue
                if ts.tzinfo is None:
                    ts = ts.replace(tzinfo=datetime.timezone.utc)
                if ts >= cutoff:
                    cnt += 1
            if cnt >= rpm:
                continue

            eligible.append(c)

        if not eligible:
            return None, _err("UNAUTHORIZED", "No active API client available for this request under current rate/quota limits.")

        # Choose the client with most remaining quota (stable-ish selection).
        eligible.sort(key=lambda c: (c.get("daily_request_quota", 0) - c.get("requests_today", 0)), reverse=True)
        client = eligible[0]

        # Atomically increment requests_today (single-process file store best-effort).
        client_id = client["id"]
        for c in clients:
            if isinstance(c, dict) and c.get("id") == client_id:
                c["requests_today"] = int(c.get("requests_today", 0)) + 1
                c["updated_at"] = _dt_to_iso(now)
                break
        _save("api_clients.json", clients)
        return client, None

    # Validate inputs
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string.")
        if status not in ["queued", "fetching", "parsing", "succeeded", "failed"]:
            return _err("VALIDATION_ERROR", "status must be one of queued, fetching, parsing, succeeded, failed.")
    if url_document_id is not None and (not isinstance(url_document_id, str) or not url_document_id.strip()):
        return _err("VALIDATION_ERROR", "url_document_id must be a non-empty string.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")
    ca = _dt_parse(created_after)
    if created_after is not None and ca is None:
        return _err("VALIDATION_ERROR", "created_after must be an ISO 8601 date-time string.")
    cb = _dt_parse(created_before)
    if created_before is not None and cb is None:
        return _err("VALIDATION_ERROR", "created_before must be an ISO 8601 date-time string.")
    if ca and cb:
        # allow equal, but not inverted
        if ca.tzinfo is None:
            ca = ca.replace(tzinfo=datetime.timezone.utc)
        if cb.tzinfo is None:
            cb = cb.replace(tzinfo=datetime.timezone.utc)
        if ca > cb:
            return _err("VALIDATION_ERROR", "created_after must be <= created_before.")
    if cursor is not None and (not isinstance(cursor, str) or not cursor):
        return _err("VALIDATION_ERROR", "cursor must be a string if provided.")

    endpoint = "list_content_fetches"
    client, e = _resolve_active_client_and_enforce_limits(endpoint)
    if e:
        _audit(endpoint, None, e["error"]["code"], (time.time() - t0) * 1000.0)
        return e

    client_id = client["id"]

    # Decode cursor
    start_after = None  # tuple(created_at, id)
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                raise ValueError("bad cursor")
            c_at = obj.get("created_at")
            c_id = obj.get("id")
            if not isinstance(c_at, str) or not isinstance(c_id, str):
                raise ValueError("bad cursor")
            d = _dt_parse(c_at)
            if d is None:
                raise ValueError("bad cursor")
            if d.tzinfo is None:
                d = d.replace(tzinfo=datetime.timezone.utc)
            start_after = (d, c_id)
        except Exception:
            _audit(endpoint, client_id, "VALIDATION_ERROR", (time.time() - t0) * 1000.0)
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    fetches = _load("content_fetches.json")
    if not isinstance(fetches, list):
        fetches = []

    # Filter to calling client + optional filters
    out = []
    for r in fetches:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != client_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if url_document_id is not None and r.get("url_document_id") != url_document_id:
            continue
        r_created = _dt_parse(r.get("created_at")) if isinstance(r.get("created_at"), str) else None
        if r_created is None:
            continue
        if r_created.tzinfo is None:
            r_created = r_created.replace(tzinfo=datetime.timezone.utc)
        if ca:
            dca = ca if ca.tzinfo else ca.replace(tzinfo=datetime.timezone.utc)
            if r_created < dca:
                continue
        if cb:
            dcb = cb if cb.tzinfo else cb.replace(tzinfo=datetime.timezone.utc)
            if r_created >= dcb:
                continue
        out.append(r)

    # Sort newest-first by created_at, tie-break id desc
    def _sort_key(r):
        d = _dt_parse(r.get("created_at")) if isinstance(r.get("created_at"), str) else None
        if d is None:
            d = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if d.tzinfo is None:
            d = d.replace(tzinfo=datetime.timezone.utc)
        return (d, str(r.get("id", "")))
    out.sort(key=_sort_key, reverse=True)

    # Apply cursor (start after the cursor tuple in this ordering)
    if start_after is not None:
        filtered = []
        for r in out:
            d = _dt_parse(r.get("created_at")) if isinstance(r.get("created_at"), str) else None
            if d is None:
                continue
            if d.tzinfo is None:
                d = d.replace(tzinfo=datetime.timezone.utc)
            rid = str(r.get("id", ""))
            # since sorted desc, "after" means strictly older (created_at <) OR same time and id < (lex) in desc ordering
            if (d < start_after[0]) or (d == start_after[0] and rid < start_after[1]):
                filtered.append(r)
        out = filtered

    total = len(out)
    page = out[:limit]
    has_more = len(out) > limit

    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_obj = {"created_at": last.get("created_at"), "id": last.get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(next_obj, ensure_ascii=False).encode("utf-8")).decode("utf-8").rstrip("=")

    latency_ms = (time.time() - t0) * 1000.0
    _audit(endpoint, client_id, "OK", latency_ms, extra={"returned": len(page)})

    return {
        "object": "list",
        "data": page,
        "client_id": client_id,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

def get_content_fetch(id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0247000" if __import__("os").path.isdir("./environment_mix/0247000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _dt_parse(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _dt_to_iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _audit(endpoint, client_id, status_code, extra=None):
        now = _now()
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row_id = f"rl_{int(time.time()*1000)}_{len(logs)+1}"
        row = {
            "id": row_id,
            "endpoint": endpoint,
            "client_id": client_id,
            "status": int(status_code),
            "latency_ms": int(latency_ms),
            "created_at": _dt_to_iso(now),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _pick_authorized_active_client_for_read(clients):
        now = _now()
        if not isinstance(clients, list):
            return None, _err("UNAUTHORIZED", "No API clients available.")
        for c in clients:
            if not isinstance(c, dict):
                continue
            if c.get("status") != "active":
                continue

            reset_at = _dt_parse(c.get("daily_reset_at"))
            if reset_at is None:
                continue
            if now >= reset_at + datetime.timedelta(days=1):
                c["daily_reset_at"] = _dt_to_iso(now)
                c["requests_today"] = 0

            quota = c.get("daily_request_quota")
            req_today = c.get("requests_today")
            if not isinstance(quota, int) or quota < 0:
                continue
            if not isinstance(req_today, int) or req_today < 0:
                req_today = 0
                c["requests_today"] = 0

            if quota == 0:
                continue
            if req_today >= quota:
                continue

            rlm = c.get("rate_limit_per_minute")
            if not isinstance(rlm, int) or rlm < 1:
                continue
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            window_start = now - datetime.timedelta(seconds=60)
            count = 0
            cid = c.get("id")
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("client_id") != cid:
                    continue
                ts = _dt_parse(r.get("created_at"))
                if ts is None:
                    continue
                if ts >= window_start:
                    count += 1
            if count >= rlm:
                continue

            c["requests_today"] = int(c.get("requests_today", 0)) + 1
            c["updated_at"] = _dt_to_iso(now)
            return c, None

        return None, _err("UNAUTHORIZED", "No active API client available within rate limits/quota.")

    endpoint = "get_content_fetch"

    # Input validation
    if not isinstance(id, str) or not id.strip():
        _audit(endpoint, None, 400, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Parameter 'id' must be a non-empty string.", param="id")

    # Ambient auth + limits
    clients = _load("api_clients.json")
    if isinstance(clients, dict) and "rows" in clients:
        clients = []
    client, auth_err = _pick_authorized_active_client_for_read(clients)
    if auth_err:
        _audit(endpoint, None, 401, {"error_code": auth_err["error"]["code"]})
        return auth_err
    _save("api_clients.json", clients)

    fetches = _load("content_fetches.json")
    if isinstance(fetches, dict) and "rows" in fetches:
        fetches = []
    if not isinstance(fetches, list):
        _audit(endpoint, client.get("id"), 500, {"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "No such content fetch id.", id=id)

    row = None
    for f in fetches:
        if isinstance(f, dict) and f.get("id") == id:
            row = f
            break

    if row is None:
        _audit(endpoint, client.get("id"), 404, {"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "No such content fetch id.", id=id)

    if row.get("client_id") != client.get("id"):
        _audit(endpoint, client.get("id"), 401, {"error_code": "UNAUTHORIZED", "target_fetch_id": id})
        return _err("UNAUTHORIZED", "Content fetch does not belong to the authenticated API client.", id=id)

    _audit(endpoint, client.get("id"), 200, {"content_fetch_id": id})
    return {"content_fetch": dict(row)}

